-- Tags: long
-- long: many statements; over the time limit of the flaky check under the thread fuzzer.

-- Key ranges and the read patterns of a query: ranges starting and ending inside the part, two ranges in one task, a skip
-- index on a sibling column and on the SHARED paths, PREWHERE, reading in order and in reverse, lazy materialization,
-- several threads, sorting and partition keys from SHARED paths, parallel replicas. Compared with a Memory table of the
-- type without SHARED; each line prints the equality flags of the three part variants.

SELECT '-- ranges starting and ending inside the part, to the end, two ranges in one task, scattered rows';
DROP TABLE IF EXISTS r_w; CREATE TABLE r_w (x UInt64, y UInt8, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8)), INDEX y_idx y TYPE minmax GRANULARITY 1) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1; INSERT INTO r_w SELECT number, intDiv(number, 4) % 2, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(60);
DROP TABLE IF EXISTS r_cm; CREATE TABLE r_cm (x UInt64, y UInt8, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8)), INDEX y_idx y TYPE minmax GRANULARITY 1) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 1; INSERT INTO r_cm SELECT number, intDiv(number, 4) % 2, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(60);
DROP TABLE IF EXISTS r_cn; CREATE TABLE r_cn (x UInt64, y UInt8, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8)), INDEX y_idx y TYPE minmax GRANULARITY 1) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 0; INSERT INTO r_cn SELECT number, intDiv(number, 4) % 2, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(60);
DROP TABLE IF EXISTS r_mem; CREATE TABLE r_mem (x UInt64, y UInt8, json JSON(a UInt64, b String, c Array(UInt8))) ENGINE = Memory; INSERT INTO r_mem SELECT number, intDiv(number, 4) % 2, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(60);
SELECT 'r [json] WHERE x >= 5 AND x < 12', (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json AS v FROM r_w WHERE x >= 5 AND x < 12  SETTINGS max_threads = 1)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json AS v FROM r_mem WHERE x >= 5 AND x < 12 )), (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json AS v FROM r_cm WHERE x >= 5 AND x < 12  SETTINGS max_threads = 1)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json AS v FROM r_mem WHERE x >= 5 AND x < 12 )), (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json AS v FROM r_cn WHERE x >= 5 AND x < 12  SETTINGS max_threads = 1)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json AS v FROM r_mem WHERE x >= 5 AND x < 12 )), (SELECT count() FROM r_w WHERE x >= 5 AND x < 12);
SELECT 'r [(json.a, json.c)] max_block_size = 4 WHERE x >= 5 AND x < 12', (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, (json.a, json.c) AS v FROM r_w WHERE x >= 5 AND x < 12  SETTINGS max_threads = 1, max_block_size = 4)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, (json.a, json.c) AS v FROM r_mem WHERE x >= 5 AND x < 12 )), (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, (json.a, json.c) AS v FROM r_cm WHERE x >= 5 AND x < 12  SETTINGS max_threads = 1, max_block_size = 4)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, (json.a, json.c) AS v FROM r_mem WHERE x >= 5 AND x < 12 )), (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, (json.a, json.c) AS v FROM r_cn WHERE x >= 5 AND x < 12  SETTINGS max_threads = 1, max_block_size = 4)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, (json.a, json.c) AS v FROM r_mem WHERE x >= 5 AND x < 12 )), (SELECT count() FROM r_w WHERE x >= 5 AND x < 12);
