SELECT 'granules r WHERE x >= 5 AND x < 12', replaceRegexpAll(explain, '^[│ ]+', '') FROM (EXPLAIN indexes = 1 SELECT sum(json.a) FROM r_w WHERE x >= 5 AND x < 12 SETTINGS max_threads = 1, use_skip_indexes = 1, use_skip_indexes_on_data_read = 0, use_query_condition_cache = 0, use_skip_indexes_if_final = 1, force_index_by_date = 0, force_primary_key = 0, optimize_use_implicit_projections = 0, optimize_trivial_count_query = 0, optimize_move_to_prewhere = 0) WHERE explain LIKE '%Granules%';
