SELECT '-- subcolumns read from disk over ranges';
DROP TABLE IF EXISTS s_w; CREATE TABLE s_w (x UInt64, y UInt8, json JSON(SHARED arr Array(UInt8), SHARED t Tuple(p UInt64, q String), SHARED d Dynamic), INDEX y_idx y TYPE minmax GRANULARITY 1) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1; INSERT INTO s_w SELECT number, intDiv(number, 4) % 2, concat('{"arr":', toString(range(number % 3)), ',"t":{"p":', toString(number), ',"q":"q', toString(number % 3), '"},"d":', if(number % 3 = 0, toString(number), concat('"d', toString(number), '"')), '}') FROM numbers(40);
DROP TABLE IF EXISTS s_cm; CREATE TABLE s_cm (x UInt64, y UInt8, json JSON(SHARED arr Array(UInt8), SHARED t Tuple(p UInt64, q String), SHARED d Dynamic), INDEX y_idx y TYPE minmax GRANULARITY 1) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 1; INSERT INTO s_cm SELECT number, intDiv(number, 4) % 2, concat('{"arr":', toString(range(number % 3)), ',"t":{"p":', toString(number), ',"q":"q', toString(number % 3), '"},"d":', if(number % 3 = 0, toString(number), concat('"d', toString(number), '"')), '}') FROM numbers(40);
DROP TABLE IF EXISTS s_cn; CREATE TABLE s_cn (x UInt64, y UInt8, json JSON(SHARED arr Array(UInt8), SHARED t Tuple(p UInt64, q String), SHARED d Dynamic), INDEX y_idx y TYPE minmax GRANULARITY 1) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 0; INSERT INTO s_cn SELECT number, intDiv(number, 4) % 2, concat('{"arr":', toString(range(number % 3)), ',"t":{"p":', toString(number), ',"q":"q', toString(number % 3), '"},"d":', if(number % 3 = 0, toString(number), concat('"d', toString(number), '"')), '}') FROM numbers(40);
DROP TABLE IF EXISTS s_mem; CREATE TABLE s_mem (x UInt64, y UInt8, json JSON(arr Array(UInt8), t Tuple(p UInt64, q String), d Dynamic)) ENGINE = Memory; INSERT INTO s_mem SELECT number, intDiv(number, 4) % 2, concat('{"arr":', toString(range(number % 3)), ',"t":{"p":', toString(number), ',"q":"q', toString(number % 3), '"},"d":', if(number % 3 = 0, toString(number), concat('"d', toString(number), '"')), '}') FROM numbers(40);
