DROP TABLE IF EXISTS r_pk; CREATE TABLE r_pk (x UInt64, y UInt8, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1, min_bytes_for_full_part_storage = 536870912; INSERT INTO r_pk SELECT number, intDiv(number, 4) % 2, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(60);
ALTER TABLE r_pk ADD INDEX ic json.c.size0 TYPE minmax GRANULARITY 1;
ALTER TABLE r_pk MATERIALIZE INDEX ic SETTINGS mutations_sync = 2;
SELECT 'r_pk [json] after the mutation', (SELECT arraySort(groupArray((x, toString(json)))) FROM r_pk SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(json)))) FROM r_mem);
ALTER TABLE r_pk UPDATE y = json.c.size0 WHERE 1 SETTINGS mutations_sync = 2;
