DROP TABLE IF EXISTS p_w; CREATE TABLE p_w (x UInt64, y UInt8, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8)), INDEX y_idx y TYPE minmax GRANULARITY 1) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1; INSERT INTO p_w SELECT number, intDiv(number, 4) % 2, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(60);
DROP TABLE IF EXISTS p_cm; CREATE TABLE p_cm (x UInt64, y UInt8, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8)), INDEX y_idx y TYPE minmax GRANULARITY 1) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 1; INSERT INTO p_cm SELECT number, intDiv(number, 4) % 2, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(60);
DROP TABLE IF EXISTS p_cn; CREATE TABLE p_cn (x UInt64, y UInt8, json JSON(SHARED a UInt64, SHARED b String, SHARED c Array(UInt8)), INDEX y_idx y TYPE minmax GRANULARITY 1) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 0; INSERT INTO p_cn SELECT number, intDiv(number, 4) % 2, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(60);
DROP TABLE IF EXISTS p_mem; CREATE TABLE p_mem (x UInt64, y UInt8, json JSON(a UInt64, b String, c Array(UInt8))) ENGINE = Memory; INSERT INTO p_mem SELECT number, intDiv(number, 4) % 2, concat('{"a":', toString(number * 10), ',"b":"', repeat('x', number % 7), '","c":', toString(range(number % 4)), if(number % 2 = 0, concat(',"d":', toString(number)), ''), '}') FROM numbers(60);
SELECT 'p [json] enable_parallel_replicas = 1, max_parallel_replicas = 3, cluster_for_parallel_replicas = \'test_cluster_one_shard_three_replicas_localhost\', parallel_replicas_for_non_replicated_merge_tree = 1, parallel_replicas_local_plan = 1', (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json AS v FROM p_w   SETTINGS max_threads = 1, enable_parallel_replicas = 1, max_parallel_replicas = 3, cluster_for_parallel_replicas = 'test_cluster_one_shard_three_replicas_localhost', parallel_replicas_for_non_replicated_merge_tree = 1, parallel_replicas_local_plan = 1)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json AS v FROM p_mem  )), (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json AS v FROM p_cm   SETTINGS max_threads = 1, enable_parallel_replicas = 1, max_parallel_replicas = 3, cluster_for_parallel_replicas = 'test_cluster_one_shard_three_replicas_localhost', parallel_replicas_for_non_replicated_merge_tree = 1, parallel_replicas_local_plan = 1)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json AS v FROM p_mem  )), (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json AS v FROM p_cn   SETTINGS max_threads = 1, enable_parallel_replicas = 1, max_parallel_replicas = 3, cluster_for_parallel_replicas = 'test_cluster_one_shard_three_replicas_localhost', parallel_replicas_for_non_replicated_merge_tree = 1, parallel_replicas_local_plan = 1)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json AS v FROM p_mem  )), (SELECT count() FROM p_w );
SELECT 'p [(json.a, json.c.size0)] enable_parallel_replicas = 1, max_parallel_replicas = 3, cluster_for_parallel_replicas = \'test_cluster_one_shard_three_replicas_localhost\', parallel_replicas_for_non_replicated_merge_tree = 1, parallel_replicas_local_plan = 1, max_block_size = 5', (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, (json.a, json.c.size0) AS v FROM p_w   SETTINGS max_threads = 1, enable_parallel_replicas = 1, max_parallel_replicas = 3, cluster_for_parallel_replicas = 'test_cluster_one_shard_three_replicas_localhost', parallel_replicas_for_non_replicated_merge_tree = 1, parallel_replicas_local_plan = 1, max_block_size = 5)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, (json.a, json.c.size0) AS v FROM p_mem  )), (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, (json.a, json.c.size0) AS v FROM p_cm   SETTINGS max_threads = 1, enable_parallel_replicas = 1, max_parallel_replicas = 3, cluster_for_parallel_replicas = 'test_cluster_one_shard_three_replicas_localhost', parallel_replicas_for_non_replicated_merge_tree = 1, parallel_replicas_local_plan = 1, max_block_size = 5)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, (json.a, json.c.size0) AS v FROM p_mem  )), (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, (json.a, json.c.size0) AS v FROM p_cn   SETTINGS max_threads = 1, enable_parallel_replicas = 1, max_parallel_replicas = 3, cluster_for_parallel_replicas = 'test_cluster_one_shard_three_replicas_localhost', parallel_replicas_for_non_replicated_merge_tree = 1, parallel_replicas_local_plan = 1, max_block_size = 5)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, (json.a, json.c.size0) AS v FROM p_mem  )), (SELECT count() FROM p_w );
SELECT 'p [json.b] enable_parallel_replicas = 1, max_parallel_replicas = 3, cluster_for_parallel_replicas = \'test_cluster_one_shard_three_replicas_localhost\', parallel_replicas_for_non_replicated_merge_tree = 1, parallel_replicas_local_plan = 1 WHERE x >= 9 AND x < 50', (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json.b AS v FROM p_w WHERE x >= 9 AND x < 50  SETTINGS max_threads = 1, enable_parallel_replicas = 1, max_parallel_replicas = 3, cluster_for_parallel_replicas = 'test_cluster_one_shard_three_replicas_localhost', parallel_replicas_for_non_replicated_merge_tree = 1, parallel_replicas_local_plan = 1)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json.b AS v FROM p_mem WHERE x >= 9 AND x < 50 )), (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json.b AS v FROM p_cm WHERE x >= 9 AND x < 50  SETTINGS max_threads = 1, enable_parallel_replicas = 1, max_parallel_replicas = 3, cluster_for_parallel_replicas = 'test_cluster_one_shard_three_replicas_localhost', parallel_replicas_for_non_replicated_merge_tree = 1, parallel_replicas_local_plan = 1)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json.b AS v FROM p_mem WHERE x >= 9 AND x < 50 )), (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json.b AS v FROM p_cn WHERE x >= 9 AND x < 50  SETTINGS max_threads = 1, enable_parallel_replicas = 1, max_parallel_replicas = 3, cluster_for_parallel_replicas = 'test_cluster_one_shard_three_replicas_localhost', parallel_replicas_for_non_replicated_merge_tree = 1, parallel_replicas_local_plan = 1)) = (SELECT arraySort(groupArray((x, toString(v)))) FROM (SELECT x, json.b AS v FROM p_mem WHERE x >= 9 AND x < 50 )), (SELECT count() FROM p_w WHERE x >= 9 AND x < 50);
DROP TABLE p_w; DROP TABLE p_cm; DROP TABLE p_cn; DROP TABLE p_mem;
